    function addCollider(path_info, collider_id) {
        let { path_type, set, path_index } = path_info
        if (colliders[collider_id]) {
            let prev_state = colliders[collider_id];
            let new_fd = [...prev_state[path_type]]
            new_fd.push(path_index)
            let new_state = { ...prev_state, [path_type]: new_fd }
            colliders = { ...colliders, [collider_id]: new_state }
        } else {
            if (path_type === "back") {
                colliders = { ...colliders, [collider_id]: { "back": [path_index], "front": [] } }
            } else {
                colliders = { ...colliders, [collider_id]: { "back": [], "front": [path_index] } }
            }
        }
        return
    }

    // find label of tab first TODO : need to set in tabs or something
    async function setLabel() {
        let cm = 0
        let km = 0
        let label = ""
        for await (const node of nodes) {
            if (node.type === "causeeffect") { cm += 1 }
            if (node.type === "entity" || node.type === "relation" || node.type === "attribute" || node.type === "rule") { km += 1 }
        }

        if (cm === km && cm === 0) {
            label = "NA"
        } else {
            label = cm > km ? "CM" : "KM"
        }
        console.log("Setting label to " + label, "total cm: " + cm, "total km " + km)
        return label
    }

