    async function fetchCausalAnalysis() {
        let req_object = {
            "dowhy": {
                "libraries": ["dowhy"],
                "labels": _labels,
                "treatment": $("#ca-treatment").val(),
                "outcome": $("#ca-outcome").val(),
                "method": $("#est-methods").val(),
            },
            "econml": {
                "libraries": ["econml"],
                "labels": _labels,
                "treatment": $("#ca-treatment").val(),
                "outcome": $("#ca-outcome").val(),
                "category": $("#estimator-categories").val(),
                "estimation_type": $("#estimator-function-type").val(),
                "estimator_type": $("#function-type").val(),
                "instrumentals": Array.from(variable_types["instrumentals"]["nodes"]),
                "controls": Array.from(variable_types["controls"]["nodes"]),
                "effect-mods": Array.from(variable_types["effect-mods"]["nodes"]),
            },
            "causalml": {},
            "causallib": {},
            "pywhy-gcm": {
                "libraries": ["pywhy-gcm"],
                "labels": _labels,
            },
        }



        // need request objects
        let tab_list = library_tabs.listTabs()
        let active_index = library_tabs.activeIndex()
        let lib = tab_list[active_index]
        let validated = true
        console.log("Library: ", lib)
        let validate_value = function (value) {
            console.log("validating value ", value)
            if (/[a-zA-Z]/.test(value)) {
                return false
            }
            // if(value === ""){
            //     return false
            // }
            return true
        }
        if (lib === "pywhy-gcm") {
            await loadNodes()
            await loadLabels()
            await createParentChildIndex();
            validated = validate_value($("#intervention-value")[0].value)
            if (!validated) {
                RED.notify("Intervention value must be a decimal or whole number ", "error")
            } else {
                if ($("#intervention-value")[0].value !== "") {
                    req_object[lib]["intervention"] = {}
                    req_object[lib]["intervention"]["variable"] = $("#intervention-variable")[0].value
                    req_object[lib]["intervention"]["value"] = $("#intervention-value")[0].value
                    req_object[lib]["intervention"]["type"] = $("#intervention-type")[0].value
                }
            }

            // add counterfactual analysis items 
            let cf_items = {}
            let list_items = d3.select("#counterfactual-container").selectAll("li")[0]
            let counterfactuals_validated = new Set()
            if (list_items !== undefined || null) {
                for (let item of list_items) {
                    let child_items = item.childNodes[0].childNodes[0].childNodes
                    let key = ""
                    let value = ""
                    for (let item of child_items) {
                        if (item.tagName === "SELECT") {
                            key = item.value
                        }
                        if (item.tagName === "INPUT") {
                            if (validate_value(item.value)) {
                                value = item.value
                                counterfactuals_validated.add(true)
                            } else {
                                counterfactuals_validated.add(false)
                                RED.notify("Error while validating counterfactual value for " + key, "error");
                            }
                        }
                        cf_items = { ...cf_items, [key]: value }
                    }
                }
            }

            let counterfactual_variable_validated = false
            counterfactual_variable_validated = validate_value($("#cf-intervention-value")[0].value)
            if (!counterfactuals_validated.has(false) &&
                counterfactuals_validated.size !== 0 &&
                counterfactual_variable_validated) {
                req_object[lib]["counterfactuals"] = {
                    "intervention": {
                        "variable": $("#counterfactual-select")[0].value,
                        "value": $("#cf-intervention-value")[0].value
                    },
                    "observed": cf_items
                }
            }

            console.log("request object: ", req_object[lib])
        }
        if (validated || counterfactuals_validated) {
            console.log(req_object[lib])
            fetch(docker_backend_uri  + ":" + port + "/causal_inference/" + model_id, {
                method: "POST",
                body: JSON.stringify(req_object[lib]),
            }).then(async res => {
                if (res.ok) {
                    if (lib === "dowhy") {
                        await dowhy_postprocess(res)
                    }
                    if (lib === "econml") {
                        await econml_postprocess(res)
                    }
                    if (lib === "pywhy-gcm") {
                        console.log("performing pywhy-gcm postprocess")
                        await pywhygcm_postprocess(res, req_object)
                        deployed_pywhy = true
                    }

                }
            })
        }
    }

